import type { OrderFormState } from "@/types/order/order.d";

/** Fields generated by the API and never trusted as an edit request source. */
const DERIVED_FIELDS = new Set(["countryName", "internationalMobile", "formattedAddress", "fullAddress"]);

/** Build the narrow request contract consumed by admin modifyConsignee. */
export const buildConsigneePayload = (id: number, state: Partial<OrderFormState> & Record<string, unknown>) => {
    const payload: Record<string, unknown> = { id };
    for (const [key, value] of Object.entries(state)) {
        if (DERIVED_FIELDS.has(key) || value === undefined) continue;
        payload[key] = value;
    }
    return payload;
};
